const {deviceState,syncDevice}=require('../../utils/page')
const {askCoach,isAuthError}=require('../../utils/api')
const {coachHelpPolicy}=require('../../utils/coach')
const PERSONAS=Object.freeze([
 {id:'keeper',name:'温和掌柜',detail:'安静听你说，也会给一点轻松回应。'},
 {id:'study-buddy',name:'学习搭子',detail:'聊聊今天的节奏、卡点或小进展。'},
 {id:'story-traveler',name:'故事旅人',detail:'交换轻巧的想象、见闻和故事灵感。'},
])
const STARTERS=['今天发生了一件小事','陪我放松两分钟','给我一个轻松的话题']
const owner=()=>String(wx.getStorageSync('stemistUser')?.id||'guest'),epoch=()=>Number(wx.getStorageSync('stemistPrivacyEpoch'))||0
Page({
 onShareAppMessage(){return require('../../utils/share').onShareAppMessage.call(this)},
 data:deviceState({personas:PERSONAS,starters:STARTERS,persona:'keeper',message:'',turns:[],answer:'',loading:false,error:'',warning:'',canRetry:false,authRequired:false,status:'',examBlocked:false}),
 onLoad(options){this.__owner=owner();this.__epoch=epoch();this.__disposed=false;this.__states={};this.__attemptId='';let blocked=false;const key=String(options?.entry||''),entry=wx.getStorageSync('stemistCoachEntry'),age=Date.now()-Number(entry?.at);if(key&&entry?.key===key&&entry.owner===this.__owner&&entry.epoch===this.__epoch&&age>=0&&age<120000){const context=entry.context||{},attempt=context.attempt||{};this.__attemptId=String(context.attemptId||context.paperAttemptId||attempt.id||attempt.attemptId||'');blocked=coachHelpPolicy(context).solutionDisabled}this.loadPersona('keeper');if(blocked)this.setData({examBlocked:true,error:'计时考试进行中，休闲酒馆暂不可用；请先完成或退出本次考试。'})},
 onShow(){syncDevice(this);if(this.__authResumeRequested&&wx.getStorageSync('stemistSessionToken')&&owner()===this.__owner&&epoch()===this.__epoch){this.__authResumeRequested=false;this.loadPersona(this.data.persona);return}if(!this.current())this.setData({message:'',turns:[],answer:'',loading:false,canRetry:false,authRequired:false,status:'',error:'账号状态已变化，请返回后重新进入酒馆。'})},onResize(){syncDevice(this)},
 onUnload(){if(this.current())this.save(false);this.__disposed=true},current(){return !this.__disposed&&this.__owner===owner()&&this.__epoch===epoch()},
 key(persona=this.data.persona){return`stemistTavern:${this.__owner}:${this.__epoch}:${persona}`},
 read(persona){let state=this.__states[persona];if(!state)try{state=wx.getStorageSync(this.key(persona))}catch{}return state&&state.owner===this.__owner&&state.epoch===this.__epoch&&state.persona===persona?state:{draft:'',turns:[]}},
 save(warn=true){if(!this.current())return false;const state={owner:this.__owner,epoch:this.__epoch,persona:this.data.persona,draft:this.data.message,turns:this.data.turns.slice(-12)};this.__states[this.data.persona]=state;try{wx.setStorageSync(this.key(),state);if(warn&&this.data.warning)this.setData({warning:''});return true}catch{if(warn)this.setData({warning:'当前对话未能保存在本机；本页内内容仍保留，请暂时不要退出。'});return false}},
 loadPersona(persona){const state=this.read(persona);this.setData({persona,message:String(state.draft||''),turns:Array.isArray(state.turns)?state.turns.slice(-12):[],answer:'',error:this.data.examBlocked?this.data.error:'',warning:'',canRetry:false,authRequired:false,status:''})},
 choosePersona(event){if(!this.current()||this.data.loading||this.data.examBlocked)return;const persona=String(event.currentTarget?.dataset?.persona||'');if(!PERSONAS.some(item=>item.id===persona)||persona===this.data.persona)return;this.save();this.loadPersona(persona)},
 onMessage(event){if(!this.current()||this.data.loading||this.data.examBlocked)return;this.setData({message:String(event.detail?.value||''),error:'',authRequired:false});this.save()},
 useStarter(event){if(!this.current()||this.data.loading||this.data.examBlocked)return;const message=String(event.currentTarget?.dataset?.text||'');if(!STARTERS.includes(message))return;this.setData({message,error:'',authRequired:false});this.save()},
 async submit(){const message=this.data.message.trim();if(!message||this.data.loading||!this.current()||this.data.examBlocked)return;if(message.length>1200)return this.setData({error:'一次最多输入 1200 个字。'});this.setData({loading:true,error:'',answer:'',canRetry:false,authRequired:false,status:'AI 正在回应…'});try{const result=await askCoach({message,feature:'tavern',persona:this.data.persona,attemptId:this.__attemptId,context:{product:'STEM Studio',skill:'tavern',stage:'practice',source:'stemist-miniprogram'},imageDataUrls:[],history:this.data.turns.slice(-10)});if(!this.current())return;const answer=String(result?.answer||result?.message||'').trim(),completed=result?.mode==='ai'&&result?.providerStatus==='connected'&&Boolean(answer);if(!completed)throw new Error(result?.failureMessage||'AI 本次没有完成回应，文字已保留，请重试。');const turns=[...this.data.turns,{role:'user',content:message},{role:'assistant',content:answer}].slice(-12);this.setData({message:'',turns,answer,status:'AI 已回应',canRetry:false});this.save()}catch(error){const auth=isAuthError(error);if(auth&&epoch()===this.__epoch&&owner()==='guest')this.setData({message:'',turns:[],answer:'',error:'登录已过期，请登录后继续。',canRetry:false,authRequired:true,status:'对话未完成',loading:false});else if(this.current()){this.setData({answer:'',error:error.message||'AI 暂时不可用，文字已保留。',canRetry:!auth,authRequired:auth,status:'对话未完成'});this.save()}}finally{if(this.current()||this.data.authRequired)this.setData({loading:false})}},
 retry(){if(!this.data.loading)this.submit()},openAccount(){this.__authResumeRequested=true;wx.navigateTo({url:'/pages/account/auth'})},
 clear(){if(this.data.loading||!this.current())return;wx.removeStorageSync(this.key());this.setData({message:'',turns:[],answer:'',error:'',canRetry:false,authRequired:false,status:'已清空当前角色对话'})},
})
